const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cuyuniPoint = ee.Geometry.Point(-58.628264, 6.437929);
  const confluencePoint = ee.Geometry.Point(-58.606792, 6.407305);
  const dateStart = '2023-08-16';
  const dateEnd = '2023-08-17';

  // 2. Data Acquisition & Cloud Masking Function
  const maskS2clouds = function(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    // Scale factor for SR bands is 10000
    return image.updateMask(mask).divide(10000).copyProperties(image, ["system:time_start"]);
  };

  // 3. Image Collection Processing
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(cuyuniPoint.merge(confluencePoint))
    .filterDate(dateStart, dateEnd);

  if (collection.size().getInfo() === 0) {
    console.log(`No Sentinel-2 images found for ${dateStart}.`);
    console.log("C1");
    return;
  }

  const maskedCollection = collection.map(maskS2clouds);
  const image = maskedCollection.mosaic(); // Mosaic to handle potential multiple tiles on the same day

  // Define an expression to calculate average brightness from visible bands
  const brightnessImage = image.expression(
    '(RED + GREEN + BLUE) / 3.0', {
      'RED': image.select('B4'),
      'GREEN': image.select('B3'),
      'BLUE': image.select('B2')
    }).rename('brightness');

  // 4. Analysis and Pixel Validation
  const scale = 10; // Sentinel-2 10m bands

  const cuyuniStats = brightnessImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: cuyuniPoint.buffer(scale), // Buffer to sample nearby pixels
    scale: scale,
    maxPixels: 10
  }).getInfo();

  const confluenceStats = brightnessImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: confluencePoint.buffer(scale),
    scale: scale,
    maxPixels: 10
  }).getInfo();

  const cuyuniBrightness = cuyuniStats.brightness_mean;
  const cuyuniPixels = cuyuniStats.brightness_count;
  const confluenceBrightness = confluenceStats.brightness_mean;
  const confluencePixels = confluenceStats.brightness_count;

  console.log(`Cuyuni River Brightness: ${cuyuniBrightness ? cuyuniBrightness.toFixed(4) : 'N/A'}, Valid Pixels: ${cuyuniPixels}`);
  console.log(`Confluence Brightness: ${confluenceBrightness ? confluenceBrightness.toFixed(4) : 'N/A'}, Valid Pixels: ${confluencePixels}`);

  // 5. Validation & Final Answer
  if (cuyuniPixels === 0 || confluencePixels === 0) {
    console.log("No valid (cloud-free) pixels found at one or both locations.");
    console.log("C2");
    return;
  }

  if (cuyuniBrightness === null || confluenceBrightness === null) {
    console.log("Calculation failed, could not retrieve brightness values.");
    console.log("C3");
    return;
  }

  if (cuyuniBrightness > confluenceBrightness) {
    console.log("The Cuyuni River appeared lighter.");
    console.log("A");
  } else {
    console.log("The Cuyuni River did not appear lighter.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred: ", err);
    console.log("D");
});
